const CACHE = 'ruralhealth-v14';
const OFFLINE_URL = '/offline.html';
const ASSETS = ['/', '/index.html', '/offline.html', '/patient.html', '/provider.html', '/provider-login.html', '/providers-in-area.html', '/styles.css', '/intro.js', '/patient.js', '/provider.js', '/provider-auth.js', '/provider-login.js', '/providers-in-area.js', '/offline-assistant.js', '/i18n.js', '/manifest.json', '/sw.js', '/sw-register.js', '/icons/icon-192.png', '/icons/icon-512.png', '/socket.io/socket.io.js', '/vendor/leaflet/leaflet.css', '/vendor/leaflet/leaflet.js', '/vendor/leaflet/images/marker-icon.png', '/vendor/leaflet/images/marker-shadow.png', '/vendor/leaflet/images/layers.png', '/vendor/leaflet/images/layers-2x.png'];

function cacheSuccessfulGet(request, response) {
  if (!response || !response.ok || request.method !== 'GET') return response;
  caches.open(CACHE).then(cache => cache.put(request, response.clone())).catch(() => {});
  return response;
}

function createApiFallbackResponse() {
  return new Response(JSON.stringify({
    ok: false,
    error: 'Network unavailable. Please check your connection and try again.'
  }), {
    status: 503,
    statusText: 'Service Unavailable',
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-store'
    }
  });
}

self.addEventListener('install', evt => {
  evt.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)));
  self.skipWaiting();
});

self.addEventListener('activate', evt => {
  evt.waitUntil(
    caches.keys().then(keys => Promise.all(
      keys.filter(k => k !== CACHE).map(k => caches.delete(k))
    ))
  );
  self.clients.claim();
});

self.addEventListener('message', evt => {
  if (evt.data && evt.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Use network-first for same-origin GET requests so UI/CSS updates appear quickly,
// fallback to cache when offline.
self.addEventListener('fetch', evt => {
  const req = evt.request;
  const url = new URL(req.url);
  const isGet = req.method === 'GET';
  const isSameOrigin = url.origin === self.location.origin;
  const isNavigation = req.mode === 'navigate';
  const isApiRequest = isSameOrigin && url.pathname.startsWith('/api/');

  if (isApiRequest) {
    evt.respondWith(
      fetch(req).catch(() => createApiFallbackResponse())
    );
    return;
  }

  if (isNavigation) {
    evt.respondWith(
      fetch(req).then(resp => {
        return cacheSuccessfulGet(req, resp);
      }).catch(async () => {
        const cachedPage = await caches.match(req);
        if (cachedPage) return cachedPage;
        return caches.match(OFFLINE_URL);
      })
    );
    return;
  }

  if (isGet && isSameOrigin) {
    evt.respondWith(
      fetch(req).then(resp => {
        return cacheSuccessfulGet(req, resp);
      }).catch(async () => {
        const cached = await caches.match(req);
        return cached || Response.error();
      })
    );
    return;
  }

  evt.respondWith(caches.match(req).then(cached => cached || fetch(req)));
});

function el(id) { return document.getElementById(id); }
const t = (key, params) => (window.appI18n ? window.appI18n.t(key, params) : key);

function setStatus(message, isError) {
  const status = el('providerLoginStatus');
  status.textContent = message;
  status.style.color = isError ? '#8d2626' : '#2b4c20';
}

async function sendAuth(path, payload) {
  let res;
  try {
    res = await fetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  } catch {
    throw new Error(t('error.networkUnavailable'));
  }

  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || t('error.requestFailed'));
  }
  return data;
}

async function loginProvider() {
  const username = el('providerLoginUsername').value.trim();
  const password = el('providerLoginPassword').value;
  if (!username || !password) {
    setStatus(t('auth.usernamePasswordRequired'), true);
    return;
  }

  setStatus(t('auth.loggingIn'), false);
  try {
    const data = await sendAuth('/api/provider/login', { username, password });
    localStorage.setItem('providerAuthToken', data.token);
    localStorage.setItem('providerUsername', data.username || username.toLowerCase());
    window.location.href = '/provider.html';
  } catch (err) {
    setStatus(err.message, true);
  }
}

async function registerProvider() {
  const username = el('providerLoginUsername').value.trim();
  const password = el('providerLoginPassword').value;
  if (!username || !password) {
    setStatus(t('auth.createNeedCredentials'), true);
    return;
  }

  setStatus(t('auth.creatingAccount'), false);
  try {
    await sendAuth('/api/provider/register', { username, password });
    setStatus(t('auth.accountCreated'), false);
  } catch (err) {
    setStatus(err.message, true);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  el('providerLoginBtn').addEventListener('click', loginProvider);
  el('providerRegisterBtn').addEventListener('click', registerProvider);
  el('providerLoginPassword').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') loginProvider();
  });
});

